mapper.update:
UPDATE doctor_schedule SET booked_slots = booked_slots - 1,
    version = version + 1, updated_at = #{now}
WHERE id = #{scheduleId} AND booked_slots > 0

mapper.sql:
FROM appointment a LEFT JOIN doctor_schedule s ON s.id = a.schedule_id
WHERE a.deleted = 0
AND a.patient_user_id = #{patientScope}
AND a.doctor_id = #{doctorScope}
AND a.status = #{filter.status}
AND a.doctor_id = #{filter.doctorId}
AND a.department_id = #{filter.departmentId}
AND a.start_time_snapshot >= #{fromUtc}
AND a.start_time_snapshot < #{toUtc}

    AND (a.appointment_no LIKE CONCAT('%', #{filter.keyword}, '%')
        OR a.patient_name_snapshot LIKE CONCAT('%', #{filter.keyword}, '%')
        OR a.patient_phone_snapshot LIKE CONCAT('%', #{filter.keyword}, '%'))

mapper.select:
SELECT a.*, s.cancel_before_minutes

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE appointment
SET status = #{toStatus}, appointment_active_key = #{activeKey},
    cancel_reason = #{cancelReason}, cancelled_at = #{cancelledAt},
    handled_by = #{handledBy}, handled_at = #{handledAt}, updated_at = #{now}
WHERE id = #{id} AND deleted = 0 AND status = #{fromStatus}

UPDATE appointment SET deleted = 1, appointment_active_key = NULL, updated_at = #{now}
WHERE id = #{id} AND deleted = 0
  AND status NOT IN ('PENDING', 'CONFIRMED')

mapper.select:
SELECT COUNT(*) FROM appointment WHERE deleted = 0
  AND start_time_snapshot >= #{fromUtc} AND start_time_snapshot < #{toUtc}
  AND doctor_id = #{doctorScope}

SELECT status, COUNT(*) AS count FROM appointment WHERE deleted = 0
  AND doctor_id = #{doctorScope}
GROUP BY status ORDER BY status

SELECT DATE_FORMAT(DATE_ADD(created_at, INTERVAL 8 HOUR), '%Y-%m-%d') AS date,
       COUNT(*) AS count
FROM appointment WHERE deleted = 0 AND created_at >= #{fromUtc}
  AND doctor_id = #{doctorScope}
GROUP BY DATE_FORMAT(DATE_ADD(created_at, INTERVAL 8 HOUR), '%Y-%m-%d')
ORDER BY date
